import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const ResponderAvaliacao = () => {
  const { id } = useParams();
  const [avaliacao, setAvaliacao] = useState(null);
  const [respostas, setRespostas] = useState([]);
  const [tempoInicio, setTempoInicio] = useState(null);

  useEffect(() => {
    const fetchAvaliacao = async () => {
      try {
        const response = await private_api.get(`/avaliacoes/${id}`);
        setAvaliacao(response.data);
        setTempoInicio(new Date());
        setRespostas(response.data.perguntas.map(() => ""));
      } catch (error) {
        console.error("Erro ao carregar avaliação:", error);
      }
    };
    fetchAvaliacao();
  }, [id]);

  const handleRespostaChange = (perguntaIndex, resposta) => {
    const novasRespostas = [...respostas];
    novasRespostas[perguntaIndex] = resposta;
    setRespostas(novasRespostas);
  };

  const handleSubmit = async () => {
    if (!avaliacao || !respostas.length) {
      alert("Avaliação ainda não carregada!");
      return;
    }

    try {
      // Verificação robusta do alunoId
      const alunoId = localStorage.getItem("userId");
      if (!alunoId) {
        alert("ID do aluno não encontrado! Faça login novamente.");
        return;
      }

      // Conversão segura para número
      const alunoIdNumber = parseInt(alunoId, 10);
      if (isNaN(alunoIdNumber)) {
        alert("ID do aluno inválido!");
        return;
      }

      console.log("Enviando alunoId:", alunoIdNumber, "Tipo:", typeof alunoIdNumber);

      const tempoFim = new Date();
      const tempoGasto = Math.floor((tempoFim - tempoInicio) / 1000);
      const tempoFormatado = `${Math.floor(tempoGasto / 60)}m ${tempoGasto % 60}s`;

      if (respostas.some(resposta => resposta === "")) {
        alert("Responda todas as perguntas antes de submeter!");
        return;
      }

      const dadosSubmissao = {
        respostas: respostas.map((resposta, index) => ({
          perguntaId: avaliacao.perguntas[index].id || index + 1,
          resposta: resposta,
        })),
        tempo: tempoFormatado,
        alunoId: alunoIdNumber,
        dataSubmissao: new Date().toISOString(),
        avaliacaoId: parseInt(id, 10),
      };

      console.log("Dados completos da submissão:", JSON.stringify(dadosSubmissao, null, 2));

      const response = await private_api.post(`/avaliacoes/${id}/submissoes`, dadosSubmissao);
      console.log("Resposta do servidor:", response.data);

      alert("Avaliação submetida com sucesso!");
      window.location.href = "/avaliacoes";
    } catch (error) {
      console.error("Erro detalhado:", {
        message: error.message,
        request: error.config?.data,
        response: error.response?.data,
      });

      const errorDetails = error.response?.data?.errors || 
                         error.response?.data?.message || 
                         "Erro desconhecido";
      alert(`Falha na submissão: ${errorDetails}`);
    }
  };

  const confirmarSubmit = () => {
    if (window.confirm("Tem certeza que deseja submeter a avaliação?")) {
      handleSubmit();
    }
  };

  if (!avaliacao) return <div>Carregando...</div>;

  return (
    <div className="container mt-4">
      <h2>{avaliacao.titulo}</h2>
      <p>{avaliacao.descricao}</p>
      <p><strong>Pontuação máxima:</strong> {avaliacao.pontuacaoMaxima} pontos</p>

      <div className="mt-4">
        {avaliacao.perguntas.map((pergunta, index) => (
          <div key={pergunta.id || index} className="card mb-3">
            <div className="card-header">
              <h5>Pergunta {index + 1}</h5>
            </div>
            <div className="card-body">
              <p>{pergunta.texto}</p>
              {avaliacao.tipo === "escolha_multipla" ? (
                <div className="list-group">
                  {pergunta.opcoes.map((opcao, opcaoIndex) => (
                    <label key={opcaoIndex} className="list-group-item">
                      <input
                        type="radio"
                        name={`pergunta-${index}`}
                        value={opcaoIndex}
                        checked={respostas[index] === opcaoIndex.toString()}
                        onChange={() => handleRespostaChange(index, opcaoIndex.toString())}
                        className="me-2"
                      />
                      {opcao}
                    </label>
                  ))}
                </div>
              ) : (
                <textarea
                  className="form-control"
                  rows="4"
                  value={respostas[index] || ""}
                  onChange={(e) => handleRespostaChange(index, e.target.value)}
                />
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="d-flex justify-content-end mb-4">
        <button className="btn btn-primary" onClick={confirmarSubmit}>
          Submeter Avaliação
        </button>
      </div>
    </div>
  );
};

export default ResponderAvaliacao;
